-- Changelog-item voor de contactpersoonkaart onder Commercieel (commit 8d89de08, CI groen).
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-20','verbeterd','Commercieel','Zoek een contactpersoon en zie wat je met hém hebt',
   'Zoek je onder Commercieel op een naam, dan krijg je die persoon nu als eigen resultaat — met zijn functie en werkgever eronder — in plaats van alleen het bedrijf. Tik erop en je ziet zijn kaart: bellen en mailen, waar hij werkt en in welke rol, zijn gegevens, de dossiers waarop hij de contactpersoon is, en de gesprekken die je met hem had. Vanuit het klantbeeld kom je er ook: tik op een naam in het blok Contactpersonen. Wat niet is ingevuld blijft weg, zodat je in één oogopslag ziet wat er wél bekend is.');
